package vip.xiaonuo.srm.collaboration;
import java.util.*;
import java.math.BigDecimal;
import cn.hutool.crypto.digest.DigestUtil;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import org.springframework.transaction.support.*;
import org.springframework.web.multipart.MultipartFile;
import vip.xiaonuo.srm.api.SrmSupplierAccessApi.Context;
import vip.xiaonuo.srm.collaboration.api.SrmCollaborationIngressApi.*;
import static vip.xiaonuo.srm.collaboration.CollaborationStore.*;
import static vip.xiaonuo.srm.collaboration.CollaborationRules.*;
import static vip.xiaonuo.srm.collaboration.CollaborationInputs.*;
@Service @RequiredArgsConstructor @Transactional(isolation=Isolation.READ_COMMITTED)
public class InvoiceService {
 final CollaborationStore x;final SettlementService settlements;
 Map<String,Object> locked(Context a,String id){var i=x.aggregate(a,"SRM_COL_INVOICE",id,false);x.lockRecon(a,s(i,"RECON_ID"));return x.aggregate(a,"SRM_COL_INVOICE",id,true);}
 void confirmed(Map<String,Object> r){require(s(r,"STATUS").equals("CONFIRMED")&&Boolean.TRUE.equals(r.get("BUYER_CONFIRMED"))&&Boolean.TRUE.equals(r.get("SUPPLIER_CONFIRMED")),409,"对账双方确认后才可登记发票");settlements.validate(r);}
 public Map<String,Object> upload(Context a,String recId,MultipartFile file){x.finance(a);var r=x.lockRecon(a,recId);confirmed(r);try{require(!file.isEmpty()&&file.getSize()<=10*1024*1024,400,"附件须为 10MB 内的 PDF/PNG/JPEG");byte[] b=file.getBytes();String mime=b.length>=5&&new String(b,0,5,java.nio.charset.StandardCharsets.US_ASCII).equals("%PDF-")?"application/pdf":b.length>=8&&(b[0]&255)==137&&b[1]==80&&b[2]==78&&b[3]==71?"image/png":b.length>=3&&(b[0]&255)==255&&(b[1]&255)==216&&(b[2]&255)==255?"image/jpeg":"";require(!mime.isEmpty(),400,"附件内容不是有效的 PDF/PNG/JPEG");String id=id(),engine=x.files.put(id,b),name=Optional.ofNullable(file.getOriginalFilename()).orElse("invoice").replaceAll("[\\\\/\\r\\n]","_");if(name.length()>128)name=name.substring(name.length()-128);TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization(){public void afterCompletion(int status){if(status!=STATUS_COMMITTED)x.files.delete(id,engine);}});x.db.update("INSERT INTO SRM_COL_FILE(ID,RECON_ID,ORG_ID,SUPPLIER_ID,FILE_NAME,MIME,CONTENT_SHA256,BYTE_SIZE,STORAGE_ENGINE,CREATED_BY,CREATED_AT) VALUES(?,?,?,?,?,?,?,?,?,?,NOW(3))",id,recId,r.get("ORG_ID"),r.get("SUPPLIER_ID"),name,mime,DigestUtil.sha256Hex(b),b.length,engine,a.userId());return Map.of("id",id,"name",name,"mime",mime,"size",b.length);}catch(java.io.IOException e){throw new vip.xiaonuo.common.exception.CommonException(400,"附件读取失败");}}
 Map<String,Object> file(String id,String rec){var rows=x.db.queryForList("SELECT * FROM SRM_COL_FILE WHERE ID=? AND RECON_ID=?",id,rec);require(rows.size()==1,404,"附件不存在或不属于本账单");return rows.get(0);}
 PrivateFile bytes(Map<String,Object> f){byte[] b=x.files.read(s(f,"ID"),s(f,"STORAGE_ENGINE"));require(DigestUtil.sha256Hex(b).equals(s(f,"CONTENT_SHA256")),409,"附件完整性检查失败");return new PrivateFile(b,s(f,"MIME"),s(f,"CONTENT_SHA256"));}
 public PrivateFile download(Context a,String id){x.finance(a);var fs=x.db.queryForList("SELECT * FROM SRM_COL_FILE WHERE ID=?",id);require(fs.size()==1,404,"附件不存在");x.recon(a,s(fs.get(0),"RECON_ID"),false);return bytes(fs.get(0));}
 void revision(Context a,Map<String,Object> i,String reason){x.db.update("INSERT INTO SRM_COL_INVOICE_REV(ID,INVOICE_ID,REVISION,FILE_ID,AMOUNT_CIPHER,REASON_CIPHER,CREATED_BY,CREATED_AT) VALUES(?,?,?,?,?,?,?,NOW(3))",id(),i.get("ID"),i.get("REVISION"),i.get("FILE_ID"),i.get("AMOUNT_CIPHER"),x.crypto.encrypt(reason),a.userId());}
 public Map<String,Object> register(Context a,String recId,Invoice p){x.finance(a);var r=x.lockRecon(a,recId);var old=x.db.queryForList("SELECT ID,REQUEST_HASH FROM SRM_COL_INVOICE WHERE RECON_ID=? AND REQUEST_KEY=?",recId,p.requestKey());if(!old.isEmpty()){require(s(old.get(0),"REQUEST_HASH").equals(x.hash(p)),409,"相同请求号的数据不同");return detail(a,s(old.get(0),"ID"));}x.version(r,p.rowVersion());confirmed(r);require(r.get("INVOICE_ID")==null,409,"本账单已有发票");invoiceMatches(x.clearAmount(r,"AMOUNT_CIPHER"),p.amount());file(p.fileId(),recId);String id=id();x.db.update("INSERT INTO SRM_COL_INVOICE(ID,ORG_ID,SUPPLIER_ID,RECON_ID,INVOICE_NO,CURRENCY,AMOUNT_CIPHER,FILE_ID,STATUS,CREATED_BY,CREATED_AT,REQUEST_KEY,REQUEST_HASH) VALUES(?,?,?,?,?,?,?,?,'REGISTERED',?,NOW(3),?,?)",id,r.get("ORG_ID"),r.get("SUPPLIER_ID"),recId,p.invoiceNo(),r.get("CURRENCY"),x.crypto.encrypt(p.amount().toPlainString()),p.fileId(),a.userId(),p.requestKey(),x.hash(p));x.db.update("UPDATE SRM_COL_RECON SET INVOICE_ID=?,ROW_VERSION=ROW_VERSION+1 WHERE ID=?",id,recId);revision(a,x.db.queryForMap("SELECT * FROM SRM_COL_INVOICE WHERE ID=?",id),"首次登记");x.audit(a,s(r,"SUPPLIER_ID"),id,"INVOICE_REGISTERED",Map.of("reconciliation",recId));return detail(a,id);}
 public Map<String,Object> revise(Context a,String id,Revise p){x.finance(a);var i=locked(a,id);x.version(i,p.rowVersion());require(s(i,"STATUS").equals("REJECTED"),409,"仅财务退回的发票可换件重提");confirmed(x.recon(a,s(i,"RECON_ID"),false));file(p.fileId(),s(i,"RECON_ID"));x.db.update("UPDATE SRM_COL_INVOICE SET FILE_ID=?,REVISION=REVISION+1,ROW_VERSION=ROW_VERSION+1,STATUS='REGISTERED',OUTBOX_ID=NULL WHERE ID=?",p.fileId(),id);revision(a,x.db.queryForMap("SELECT * FROM SRM_COL_INVOICE WHERE ID=?",id),p.reason());return detail(a,id);}
 public Map<String,Object> push(Context a,String id,Version p){x.finance(a);require(!a.portal(),403,"仅内部财务可推送共享中心");var i=locked(a,id);if(s(i,"STATUS").equals("AWAITING_RECEIPT"))return detail(a,id);x.version(i,p.rowVersion());require(s(i,"STATUS").equals("REGISTERED"),409,"发票当前不可推送");var r=x.recon(a,s(i,"RECON_ID"),false);confirmed(r);var f=file(s(i,"FILE_ID"),s(r,"ID"));bytes(f);String out=x.exchange.enqueue(s(i,"ORG_ID"),"FINANCE",s(r,"MODE"),"FIN_INVOICE",id,n(i,"REVISION"),Map.of("invoiceId",id,"revision",n(i,"REVISION"),"invoiceNo",s(i,"INVOICE_NO"),"reconciliation",s(r,"REC_NO"),"amount",x.clearAmount(i,"AMOUNT_CIPHER"),"currency",s(i,"CURRENCY"),"sha256",s(f,"CONTENT_SHA256"),"filePath","/srm-integration/v1/invoices/"+id+"/revisions/"+n(i,"REVISION")+"/file"),a.userId());x.db.update("UPDATE SRM_COL_INVOICE SET OUTBOX_ID=?,STATUS='AWAITING_RECEIPT',ROW_VERSION=ROW_VERSION+1 WHERE ID=?",out,id);return detail(a,id);}
 public Map<String,Object> requestPayment(Context a,String id,Version p){x.finance(a);require(!a.portal(),403,"仅内部财务可发起付款申请");var i=locked(a,id);x.version(i,p.rowVersion());require(Set.of("ACCEPTED","PARTIALLY_PAID").contains(s(i,"STATUS")),409,"财务受理后才能申请付款");var r=x.recon(a,s(i,"RECON_ID"),false);confirmed(r);String out=x.exchange.enqueue(s(i,"ORG_ID"),"FINANCE",s(r,"MODE"),"FIN_PAYMENT_REQUEST",id,n(i,"REVISION"),Map.of("invoiceId",id,"revision",n(i,"REVISION"),"invoiceNo",i.get("INVOICE_NO"),"currency",i.get("CURRENCY"),"amount",x.clearAmount(i,"AMOUNT_CIPHER")),a.userId());x.audit(a,s(i,"SUPPLIER_ID"),id,"FIN_PAYMENT_REQUESTED",Map.of("outboxId",out,"revision",i.get("REVISION")));return detail(a,id);}
 public Map<String,Object> detail(Context a,String id){x.finance(a);var i=x.aggregate(a,"SRM_COL_INVOICE",id,false);var r=x.recon(a,s(i,"RECON_ID"),false);var out=x.basic(i,new String[][]{{"id","ID"},{"reconId","RECON_ID"},{"invoiceNo","INVOICE_NO"},{"currency","CURRENCY"},{"revision","REVISION"},{"rowVersion","ROW_VERSION"},{"status","STATUS"},{"fileId","FILE_ID"}});out.put("mode",r.get("MODE"));out.put("amount",x.price(a)?x.clearAmount(i,"AMOUNT_CIPHER"):"***");out.put("delivery",i.get("OUTBOX_ID")==null?Map.of():x.exchange.delivery(s(i,"ORG_ID"),s(i,"OUTBOX_ID")));var requests=x.db.queryForList("SELECT ID FROM SRM_XCH_OUTBOX WHERE ORG_ID=? AND BUSINESS_TYPE='FIN_PAYMENT_REQUEST' AND BUSINESS_ID=? AND BUSINESS_VERSION=?",i.get("ORG_ID"),id,i.get("REVISION"));out.put("paymentApplication",requests.isEmpty()?Map.of():x.exchange.delivery(s(i,"ORG_ID"),s(requests.get(0),"ID")));out.put("acknowledgements",x.db.queryForList("SELECT REVISION AS revision,RESULT AS result,REMOTE_REF AS remoteRef,APPLIED AS applied,CREATED_AT AS createdAt FROM SRM_COL_ACK WHERE INVOICE_ID=? ORDER BY CREATED_AT",id));out.put("revisions",x.db.queryForList("SELECT REVISION AS revision,FILE_ID AS fileId,CREATED_AT AS createdAt FROM SRM_COL_INVOICE_REV WHERE INVOICE_ID=? ORDER BY REVISION",id));BigDecimal paid=BigDecimal.ZERO;for(var p:x.db.queryForList("SELECT AMOUNT_CIPHER FROM SRM_COL_PAYMENT WHERE INVOICE_ID=?",id))paid=paid.add(x.clearAmount(p,"AMOUNT_CIPHER"));out.put("paidAmount",x.price(a)?paid:"***");return out;}
 Map<String,Object> trusted(Origin o,String id){var a=x.system(o);var i=locked(a,id);var r=x.recon(a,s(i,"RECON_ID"),false);require(o.orgId().equals(s(i,"ORG_ID"))&&o.mode().equals(s(r,"MODE")),403,"回执范围不匹配");return i;}
 public Map<String,Object> acknowledgement(Origin o,Command c){var p=x.input(c.data(),SourceAck.class);require(o.system().equals("FINANCE")&&c.businessKey().equals(p.invoiceId()+":"+p.revision()),400,"财务回执标识无效");var i=trusted(o,p.invoiceId());var d=x.exchange.delivery(o.orgId(),p.outboxId());require(o.connectorId().equals(d.get("connectorId")),403,"回执渠道不匹配");var out=x.db.queryForMap("SELECT BUSINESS_ID,BUSINESS_VERSION,BUSINESS_TYPE FROM SRM_XCH_OUTBOX WHERE ID=?",p.outboxId());require(p.invoiceId().equals(s(out,"BUSINESS_ID"))&&p.revision()==n(out,"BUSINESS_VERSION")&&s(out,"BUSINESS_TYPE").equals("FIN_INVOICE"),409,"回执不对应已推送发票版本");var old=x.db.queryForList("SELECT RESULT,REMOTE_REF FROM SRM_COL_ACK WHERE INVOICE_ID=? AND REVISION=?",p.invoiceId(),p.revision());for(var prev:old)require(p.result().equals(s(prev,"RESULT"))&&p.remoteRef().equals(s(prev,"REMOTE_REF")),409,"同一发票版本出现矛盾回执");boolean applied=p.revision()==n(i,"REVISION")&&Set.of("AWAITING_RECEIPT",p.result()).contains(s(i,"STATUS"));x.db.update("INSERT INTO SRM_COL_ACK(ID,INVOICE_ID,REVISION,CONNECTOR_ID,EVENT_KEY,RESULT,REMOTE_REF,MESSAGE_CIPHER,APPLIED,CREATED_AT) VALUES(?,?,?,?,?,?,?,?,?,NOW(3))",id(),p.invoiceId(),p.revision(),o.connectorId(),c.eventId(),p.result(),p.remoteRef(),x.crypto.encrypt(Optional.ofNullable(p.message()).orElse("")),applied);if(applied){x.db.update("UPDATE SRM_COL_INVOICE SET STATUS=?,ROW_VERSION=ROW_VERSION+1 WHERE ID=?",p.result(),p.invoiceId());x.notifyBoth(i,p.invoiceId(),"FINANCE_ACK","共享财务已返回发票受理结果",c.eventId());}return Map.of("applied",applied);}
 public PrivateFile invoiceFile(Origin o,String id,long rev){require(o.system().equals("FINANCE"),403,"仅授权财务渠道可读取");var i=trusted(o,id);var rows=x.db.queryForList("SELECT FILE_ID FROM SRM_COL_INVOICE_REV WHERE INVOICE_ID=? AND REVISION=?",id,rev);require(rows.size()==1,404,"发票版本不存在");var out=x.db.queryForList("SELECT CONNECTOR_ID FROM SRM_XCH_OUTBOX WHERE BUSINESS_TYPE='FIN_INVOICE' AND BUSINESS_ID=? AND BUSINESS_VERSION=?",id,rev);require(out.size()==1&&o.connectorId().equals(s(out.get(0),"CONNECTOR_ID")),403,"未向本渠道推送该版本");return bytes(file(s(rows.get(0),"FILE_ID"),s(i,"RECON_ID")));}
 public Map<String,Object> payment(Origin o,Command c){var p=x.input(c.data(),SourcePayment.class);require(c.businessKey().equals(p.paymentRef()),400,"付款流水标识不匹配");var i=trusted(o,p.invoiceId());require(Set.of("ACCEPTED","PARTIALLY_PAID","PAID").contains(s(i,"STATUS")),409,"财务尚未受理该发票");require(p.currency().equals(s(i,"CURRENCY")),409,"付款币种不匹配");if(o.system().equals("FINANCE")){require(o.connectorId().equals(x.exchange.delivery(o.orgId(),s(i,"OUTBOX_ID")).get("connectorId")),403,"付款渠道不匹配");}else{require(o.system().equals("ERP"),403,"不支持此付款渠道");require(x.db.queryForObject("SELECT COUNT(*) FROM SRM_COL_RECON_LINE l JOIN SRM_COL_PO p ON p.ID=l.PO_ID WHERE l.RECON_ID=? AND p.CONNECTOR_ID<>?",Long.class,i.get("RECON_ID"),o.connectorId())==0,403,"ERP 付款渠道不匹配");}require(p.paidAt()<=x.now()+300000,400,"付款时间不能在未来");var prior=x.db.queryForList("SELECT * FROM SRM_COL_PAYMENT WHERE CONNECTOR_ID=? AND PAYMENT_REF=?",o.connectorId(),p.paymentRef());BigDecimal total=BigDecimal.ZERO;for(var row:x.db.queryForList("SELECT * FROM SRM_COL_PAYMENT WHERE INVOICE_ID=?",p.invoiceId()))if(prior.isEmpty()||!s(row,"ID").equals(s(prior.get(0),"ID")))total=total.add(x.clearAmount(row,"AMOUNT_CIPHER"));if(!prior.isEmpty())require(s(prior.get(0),"INVOICE_ID").equals(p.invoiceId())&&c.version()==n(prior.get(0),"SOURCE_VERSION")+1,409,"付款版本或发票标识不匹配");total=total.add(p.amount());require(total.compareTo(x.clearAmount(i,"AMOUNT_CIPHER"))<=0,409,"累计付款不能超过发票金额");x.db.update("INSERT INTO SRM_COL_PAYMENT(ID,INVOICE_ID,CONNECTOR_ID,PAYMENT_REF,SOURCE_VERSION,AMOUNT_CIPHER,PAID_MS,CREATED_AT) VALUES(?,?,?,?,?,?,?,NOW(3)) ON DUPLICATE KEY UPDATE SOURCE_VERSION=VALUES(SOURCE_VERSION),AMOUNT_CIPHER=VALUES(AMOUNT_CIPHER),PAID_MS=VALUES(PAID_MS)",id(),p.invoiceId(),o.connectorId(),p.paymentRef(),c.version(),x.crypto.encrypt(p.amount().toPlainString()),p.paidAt());x.db.update("UPDATE SRM_COL_INVOICE SET STATUS=?,ROW_VERSION=ROW_VERSION+1 WHERE ID=?",total.compareTo(x.clearAmount(i,"AMOUNT_CIPHER"))==0?"PAID":"PARTIALLY_PAID",p.invoiceId());x.audit(x.system(o),s(i,"SUPPLIER_ID"),p.invoiceId(),"PAYMENT_RECEIPT_APPLIED",Map.of("reference",p.paymentRef(),"mode",o.mode()));return Map.of("applied",true);}
}
